/**
 * layers/uy/mtop.js — Capas del MTOP Uruguay
 *
 * Ministerio de Transporte y Obras Públicas — https://geoservicios.mtop.gub.uy/geoserver/ows
 * Catálogo completo: 267 capas. Todas incluidas; curación en visible/special/clipStrategy.
 *
 * Convenciones:
 *  - Keys con sufijo _uy para evitar colisión entre países.
 *  - special: false            → capa general de uso público
 *  - special: 'historico'      → datos de períodos pasados
 *  - special: 'cartografico'   → geodesia, referencia
 *  - special: 'administrativo' → regionalizaciones internas de organismos
 *  - special: 'auxiliar'       → capas de soporte, duplicados, pruebas, mapas base locales
 *  - visible: true   → se muestra por defecto en el catálogo de la UI
 *  - visible: false  → disponible para el LLM, oculta en la UI por defecto
 */

